108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        // Normalize the address up front so every downstream use (the required-field check,
122	        // household-duplicate detection, the shared household id and the stored/returned value)
123	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
124	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
125	        // supplied line is normalized the same way, and the composed address is the normalized
126	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
127	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
128	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
129	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
130	        String normalizedAddress;
131	        if (structuredAddress) {
132	            normalizedAddress = normalizedAddressLine2.isEmpty()
133	                ? normalizedAddressLine1
134	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
135	        } else {
136	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
137	        }
138	        List<String> missingFields = new ArrayList<>();
139	        if (isBlank(ownerFieldsDto.getFirstName())) {
140	            missingFields.add("firstName");
141	        }
142	        if (isBlank(ownerFieldsDto.getLastName())) {
143	            missingFields.add("lastName");
144	        }
145	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
146	        if (isBlank(normalizedAddress)) {
147	            missingFields.add("address");
148	        }
149	        if (isBlank(ownerFieldsDto.getCity())) {
150	            missingFields.add("city");
151	        }
152	        if (isBlank(ownerFieldsDto.getTelephone())) {
153	            missingFields.add("telephone");
154	        }
155	        if (!missingFields.isEmpty()) {
156	            throw new InvalidOwnerFieldsException(missingFields);
157	        }
158	        // A supplied registration date may not lie in the future: reject with 400 when the caller
159	        // provides a date later than the server's current date. Checked against the raw supplied value
160	        // (before any business-day adjustment) so a future date is never silently accepted.
161	        if (ownerFieldsDto.getRegistrationDate() != null
162	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
163	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
164	        }
165	        // Determine the effective registration date up front so every downstream use (the daily
166	        // create-limit, the stored value and anything derived from it such as the membership number's
167	        // year segment) works from the same business-day-adjusted date. The effective date is the
168	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
169	        // forward to the following Monday.
170	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
171	            ? ownerFieldsDto.getRegistrationDate()
172	            : LocalDate.now();
173	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
174	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
175	        // already carry this adjusted business day's registration date, no further owners may be
176	        // created for that day.
177	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
178	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
179	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
180	        }
181	        // Flag a bulk signup once more than 80 owners have already been created for this
182	        // business day, sharing the same daily accumulation path as the create-limit rule above.
183	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
184	        // Reject the request when the owner's city is already full: a city that already holds the
185	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
186	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
188	        }
189	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
190	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
191	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
192	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
193	        // Normalize the telephone into E.164 form; a number that cannot form a valid
194	        // E.164 value is rejected with a 400.
195	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
196	        // Email is optional; when present it must be a syntactically valid address and is
197	        // stored lower-cased. An invalid address is rejected with a 400.
198	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
199	        // Derive the household id up front. It is a deterministic function of the normalized last name
200	        // and the postcode, so owners sharing a last name and postcode independently derive the same
201	        // value and are the same household. It is always computed (never null), regardless of whether
202	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
203	        // duplicate block below.
204	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
205	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
206	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        // All duplicate detection is consolidated into a single derived identity key:
208	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
209	        // part of the key, two members of the same household (same householdId) with different
210	        // telephones have different keys and are both allowed; only an exact whole-key match is a
211	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
212	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
213	        boolean identityInUse = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> !existing.isDeleted())
215	            .anyMatch(existing -> identityKey.equals(
216	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
217	        if (identityInUse) {
218	            throw new DuplicateOwnerIdentityException(identityKey);
219	        }
220	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
221	        // computed household id is already a member of this household. A second such owner is rejected
222	        // as a household duplicate (409) unless the caller declares 'sharesHousehold', which bypasses
223	        // the block and admits the owner as a declared household member.
224	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
225	            .filter(existing -> !existing.isDeleted())
226	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
227	        if (householdMemberExists && !sharesHousehold) {
228	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
229	        }
230	        HttpHeaders headers = new HttpHeaders();
231	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
232	        // Store the composed, normalized address plus the normalized structured lines. The structured
233	        // lines are only retained when the owner was supplied in the structured form; a flat-address
234	        // owner keeps them null.
235	        owner.setAddress(normalizedAddress);
236	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
237	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
238	            ? normalizedAddressLine2 : null);
239	        owner.setTelephone(normalizedTelephone);
240	        owner.setEmail(normalizedEmail);
241	        owner.setHouseholdId(householdId);
242	        // Record how many existing owners (before this create) share this owner's first and last
243	        // name, compared case-insensitively. Computed against the current owners so the new owner
244	        // itself is never counted.
245	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
246	        // Record the size of this owner's household (owners sharing the same householdId) after this
247	        // create: the existing members already stamped with the shared identifier plus this new
248	        // owner. An owner not admitted into any household is a household of one.
249	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
250	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
251	        owner.setBulkSignupWarning(bulkSignupWarning);
252	        // Store the business-day-adjusted effective registration date computed above. This defaults
253	        // to the server's current date when none was supplied and rolls any weekend date forward to
254	        // the following Monday, so everything derived from it (e.g. the membership number's year
255	        // segment) uses the adjusted date.
256	        owner.setRegistrationDate(effectiveRegistrationDate);
257	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
258	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
259	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
260	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
261	        // Compute the base code, then de-duplicate it: if the computed value collides with an
262	        // existing owner's customerCode, append '-<n>' using the smallest n of 2 or more that
263	        // yields a value no existing owner already carries.
264	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
265	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName())));
266	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
267	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
268	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
269	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
270	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
271	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
272	        // with no matched id.
273	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
274	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
275	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
276	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
277	        this.clinicService.saveOwner(owner);
278	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
279	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
280	        // customer code, the effective registration date, the numeric membership level and the
281	        // assigned membership number.
282	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
283	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
284	            ownerDto.getMembershipNumber());
285	        headers.setLocation(UriComponentsBuilder.newInstance()
286	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
287	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
288	    }
289	
290	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
291	    @Override
292	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
293	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
294	        if (currentOwner == null) {
295	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	        }
297	        currentOwner.setAddress(ownerFieldsDto.getAddress());
298	        currentOwner.setCity(ownerFieldsDto.getCity());
299	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
300	        currentOwner.setLastName(ownerFieldsDto.getLastName());
301	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
302	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
303	        this.clinicService.saveOwner(currentOwner);
304	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Transactional
309	    @Override
310	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        // Soft delete: flag the owner deleted and retain the row rather than removing it, so the
316	        // owner is still readable via GET afterwards (now carrying 'deleted' true) while the create
317	        // endpoint's duplicate/identity checks below skip it.
318	        owner.setDeleted(true);
319	        this.clinicService.saveOwner(owner);
320	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
321	    }
322	
323	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
324	    @Override
325	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
326	        Owner owner = this.clinicService.findOwnerById(ownerId);
327	        if (owner == null) {
328	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
329	        }
330	        HttpHeaders headers = new HttpHeaders();
331	        Pet pet = petMapper.toPet(petFieldsDto);
332	        owner.setId(ownerId);
333	        pet.setOwner(owner);
334	        pet.getType().setName(null);
335	        this.clinicService.savePet(pet);
336	        PetDto petDto = petMapper.toPetDto(pet);
337	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
338	            .buildAndExpand(pet.getId()).toUri());
339	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
340	    }
341	
342	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
343	    @Override
344	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
345	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
346	        if (currentOwner != null) {
347	            Pet currentPet = this.clinicService.findPetById(petId);
348	            if (currentPet != null) {
349	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
350	                currentPet.setName(petFieldsDto.getName());
351	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
352	                this.clinicService.savePet(currentPet);
353	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
354	            }
355	        }
356	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	    }
358	
359	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
360	    @Override
361	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
362	        HttpHeaders headers = new HttpHeaders();
363	        Visit visit = visitMapper.toVisit(visitFieldsDto);
364	        Pet pet = new Pet();
365	        pet.setId(petId);
366	        visit.setPet(pet);
367	        this.clinicService.saveVisit(visit);
368	        VisitDto visitDto = visitMapper.toVisitDto(visit);
369	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
370	            .buildAndExpand(visit.getId()).toUri());
371	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
372	    }
373	
374	
375	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
376	    @Override
377	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
378	        Owner owner = this.clinicService.findOwnerById(ownerId);
379	        if (owner != null) {
380	            Pet pet = owner.getPet(petId);
381	            if (pet != null) {
382	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
383	            }
384	        }
385	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	    }
387	
388	    private static boolean isBlank(String value) {
389	        return value == null || value.trim().isEmpty();
390	    }
391	
392	    /**
393	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
394	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
395	     * compared case-insensitively with collapsed whitespace.
396	     */
397	    private static String collapse(String value) {
398	        if (value == null) {
399	            return "";
400	        }
401	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
402	    }
403	
404	    /**
405	     * Common street-type abbreviations expanded during address normalization.
406	     */
407	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
408	        "ST", "STREET",
409	        "RD", "ROAD",
410	        "AVE", "AVENUE");
411	
412	    /**
413	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
414	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
415	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
416	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
417	     * address maps to itself.
418	     */
419	    private static String normalizeAddress(String value) {
420	        if (value == null) {
421	            return "";
422	        }
423	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
424	        if (collapsed.isEmpty()) {
425	            return "";
426	        }
427	        String[] tokens = collapsed.split(" ");
428	        StringBuilder sb = new StringBuilder(collapsed.length());
429	        for (int i = 0; i < tokens.length; i++) {
430	            if (i > 0) {
431	                sb.append(' ');
432	            }
433	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
434	        }
435	        return sb.toString();
436	    }
437	
438	    /**
439	     * Derive the stable household identifier shared by owners with the same normalized last name
440	     * and postcode. It is a deterministic function of those two values, so every member of a
441	     * household independently derives the same identifier: the first 12 upper-case hex characters
442	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
443	     * an empty segment.
444	     */
445	    private static String householdId(String normalizedLastName, String postcode) {
446	        try {
447	            byte[] digest = MessageDigest.getInstance("SHA-256")
448	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
449	                    .getBytes(StandardCharsets.UTF_8));
450	            StringBuilder sb = new StringBuilder(digest.length * 2);
451	            for (byte b : digest) {
452	                sb.append(String.format("%02x", b));
453	            }
454	            return sb.substring(0, 12).toUpperCase();
455	        }
456	        catch (NoSuchAlgorithmException e) {
457	            throw new IllegalStateException("SHA-256 not available", e);
458	        }
459	    }
460	
461	    /**
462	     * Derive the identity key into which all duplicate detection is consolidated:
463	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
464	     * household id contributes an empty segment. Two owners are duplicates only when their whole
465	     * identity keys are equal.
466	     */
467	    private static String identityKey(String telephone, String email, String householdId) {
468	        return (telephone == null ? "" : telephone)
469	            + "|" + (email == null ? "" : email)
470	            + "|" + (householdId == null ? "" : householdId);
471	    }
472	
473	    /**
474	     * Count the existing owners that share the given first and last name, compared
475	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
476	     * namesakes that already existed at creation time (the new owner itself is not included).
477	     */
478	    private int countNamesakes(String firstName, String lastName) {
479	        return (int) this.clinicService.findAllOwners().stream()
480	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
481	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
482	                && existing.getLastName().equalsIgnoreCase(lastName))
483	            .count();
484	    }
485	
486	    /**
487	     * Count the existing owners that already belong to the given household (i.e. carry the same
488	     * non-null householdId). Called after any existing members have been backfilled with the shared
489	     * identifier but before the new owner is saved, so the returned value reflects the members that
490	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
491	     * new owner is not part of any household ({@code householdId} is null).
492	     */
493	    private int countHouseholdMembers(String householdId) {
494	        if (householdId == null) {
495	            return 0;
496	        }
497	        return (int) this.clinicService.findAllOwners().stream()
498	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
499	            .count();
500	    }
501	
502	    /**
503	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
504	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
505	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
506	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
507	     * including when the new owner has no last name or postcode, since a shared postcode is required
508	     * to match.
509	     */
510	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
511	        if (isBlank(lastName) || isBlank(postcode)) {
512	            return null;
513	        }
514	        return this.clinicService.findAllOwners().stream()
515	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
516	            .filter(existing -> postcode.equals(existing.getPostcode()))
517	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
518	            .min(java.util.Comparator.comparing(Owner::getId))
519	            .orElse(null);
520	    }
521	
522	    /**
523	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
524	     * request to create another owner in it is rejected as a conflict.
525	     */
526	    private static final int MAX_OWNERS_PER_CITY = 50;
527	
528	    /**
529	     * Count the existing owners registered in the given city, compared case-insensitively (as in
530	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
531	     * reflects the owners that already existed at creation time.
532	     */
533	    private int countOwnersInCity(String city) {
534	        return (int) this.clinicService.findAllOwners().stream()
535	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
536	            .count();
537	    }
538	
539	    /**
540	     * The maximum number of owners that may be created on a single day. Once this many owners
541	     * already carry a given day's registration date, a request to create another owner that day is
542	     * rejected with a 429.
543	     */
544	    private static final int MAX_OWNERS_PER_DAY = 100;
545	
546	    /**
547	     * The number of owners that may be created on a single day before the bulk-signup warning is
548	     * flagged. Once more than this many owners already carry a given day's registration date, a
549	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
550	     */
551	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
552	
553	    /**
554	     * Count the existing owners whose registration date is the given day. Called before the new
555	     * owner is saved, so the returned value reflects the owners that already existed at creation
556	     * time.
557	     */
558	    private int countOwnersRegisteredOn(LocalDate date) {
559	        return (int) this.clinicService.findAllOwners().stream()
560	            .filter(existing -> date.equals(existing.getRegistrationDate()))
561	            .count();
562	    }
563	
564	    /** Fixed public holidays the business-day roll skips. */
565	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
566	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
567	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
568	
569	    /**
570	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
571	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
572	     * business day is returned unchanged. Used so the effective registration date (whether supplied
573	     * or defaulted) always falls on a business day.
574	     */
575	    private static LocalDate toBusinessDay(LocalDate date) {
576	        while (isWeekendOrHoliday(date)) {
577	            date = date.plusDays(1);
578	        }
579	        return date;
580	    }
581	
582	    private static boolean isWeekendOrHoliday(LocalDate date) {
583	        return switch (date.getDayOfWeek()) {
584	            case SATURDAY, SUNDAY -> true;
585	            default -> PUBLIC_HOLIDAYS.contains(date);
586	        };
587	    }
588	
589	    /**
590	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
591	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
592	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
593	     */
594	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
595	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
596	    }
597	
598	    /**
599	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
600	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
601	     * {@code n} of 2 or more that produces a value no existing owner already carries.
602	     */
603	    private String deduplicateCustomerCode(String base) {
604	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
605	            .map(Owner::getCustomerCode)
606	            .filter(java.util.Objects::nonNull)
607	            .collect(java.util.stream.Collectors.toSet());
608	        if (!inUse.contains(base)) {
609	            return base;
610	        }
611	        int n = 2;
612	        while (inUse.contains(base + "-" + n)) {
613	            n++;
614	        }
615	        return base + "-" + n;
616	    }
617	
618	    /**
619	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
620	     */
621	    private static String hash8(String input) {
622	        try {
623	            byte[] digest = MessageDigest.getInstance("SHA-256")
624	                .digest(input.getBytes(StandardCharsets.UTF_8));
625	            StringBuilder sb = new StringBuilder(digest.length * 2);
626	            for (byte b : digest) {
627	                sb.append(String.format("%02x", b));
628	            }
629	            return sb.substring(0, 8).toUpperCase();
630	        }
631	        catch (NoSuchAlgorithmException e) {
632	            throw new IllegalStateException("SHA-256 not available", e);
633	        }
634	    }
635	
636	    /**
637	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
638	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
639	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
640	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
641	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
642	     * always agree.
643	     */
644	    private static String deriveRegion(String postcode, String city) {
645	        if (postcode != null && postcode.matches("\\d{4}")) {
646	            int value = Integer.parseInt(postcode);
647	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
648	                int[] range = entry.getValue();
649	                if (value >= range[0] && value <= range[1]) {
650	                    return entry.getKey();
651	                }
652	            }
653	        }
654	        if (city == null) {
655	            return "UNKNOWN";
656	        }
657	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
658	    }
659	
660	    /**
661	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
662	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
663	     * and accepts any 4-digit postcode.
664	     */
665	    private static final Map<String, String> CITY_REGION = Map.of(
666	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
667	
668	    /**
669	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
670	     * Each entry is a two-element {@code {low, high}} array.
671	     */
672	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
673	        "NSW", new int[] {2000, 2099},
674	        "VIC", new int[] {3000, 3099},
675	        "QLD", new int[] {4000, 4099});
676	
677	    /**
678	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
679	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
680	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
681	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
682	     * 4-digit postcode. A malformed or out-of-range postcode throws an
683	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
684	     */
685	    private static void validatePostcode(String city, String postcode) {
686	        if (postcode == null || postcode.isEmpty()) {
687	            return;
688	        }
689	        if (!postcode.matches("\\d{4}")) {
690	            throw new InvalidOwnerFieldsException(List.of("postcode"));
691	        }
692	        String region = city == null ? null : CITY_REGION.get(city);
693	        if (region == null) {
694	            return;
695	        }
696	        int[] range = REGION_POSTCODES.get(region);
697	        int value = Integer.parseInt(postcode);
698	        if (value < range[0] || value > range[1]) {
699	            throw new InvalidOwnerFieldsException(List.of("postcode"));
700	        }
701	    }
702	
703	    /**
704	     * Required national-number length for each E.164 country calling code we validate: a
705	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
706	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
707	     */
708	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
709	        "1", 10,
710	        "61", 9);
711	
712	    /**
713	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
714	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
715	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
716	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
717	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
718	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
719	     * rejected with a 400.
720	     */
721	    private static String toE164(String raw) {
722	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
723	        boolean hasCountryCode = cleaned.startsWith("+");
724	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
725	        if (!digits.matches("\\d+")) {
726	            throw new InvalidOwnerFieldsException(List.of("telephone"));
727	        }
728	        if (!hasCountryCode) {
729	            if (digits.startsWith("0")) {
730	                digits = digits.substring(1);
731	            }
732	            digits = "61" + digits;
733	        }
734	        if (digits.length() < 8 || digits.length() > 15) {
735	            throw new InvalidOwnerFieldsException(List.of("telephone"));
736	        }
737	        // For a recognised country code, the national number (the digits after the code) must be
738	        // exactly the expected length for that country. Match the longest known code so a shorter
739	        // code that is a prefix of another cannot mask it.
740	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
741	            if (digits.length() <= codeLength) {
742	                continue;
743	            }
744	            String countryCode = digits.substring(0, codeLength);
745	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
746	            if (requiredNationalLength != null) {
747	                if (digits.length() - codeLength != requiredNationalLength) {
748	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
749	                }
750	                break;
751	            }
752	        }
753	        return "+" + digits;
754	    }
755	
756	    /**
757	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
758	     * and a domain with at least one dot-separated label, none of which contain whitespace or
759	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
760	     */
761	    private static final Pattern EMAIL_PATTERN =
762	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
763	
764	    /**
765	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
766	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
767	     */
768	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
769	        "mailinator.com", "tempmail.com", "guerrillamail.com");
770	
771	    /**
772	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
773	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
774	     * domain is not on the disposable-domain blocklist, otherwise an
775	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
776	     * address is returned lower-cased.
777	     */
778	    private static String normalizeEmail(String email) {
779	        if (email == null || email.isEmpty()) {
780	            return null;
781	        }
782	        String trimmed = email.trim();
783	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
784	            throw new InvalidOwnerFieldsException(List.of("email"));
785	        }
786	        String normalized = trimmed.toLowerCase();
787	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
788	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
789	            throw new InvalidOwnerFieldsException(List.of("email"));
790	        }
791	        return normalized;
792	    }
793	}
